import{_ as s,a}from"./chunks/isaac-sim-rbq-test.DJ9nZooS.js";import{_ as e,o as i,c as o,a5 as r}from"./chunks/framework.BMR-TWOq.js";const b=JSON.parse('{"title":"Isaac Sim","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/isaac-sim.md","filePath":"software/simulator/isaac-sim.md","lastUpdated":1794894003000}'),d={name:"software/simulator/isaac-sim.md"};function n(h,t,l,c,p,m){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="isaac-sim" tabindex="-1">Isaac Sim <a class="header-anchor" href="#isaac-sim" aria-label="Permalink to &quot;Isaac Sim&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Isaac Sim simulator for the RBQ quadruped robot.</strong></p><p>Isaac Sim runs the <strong>full RBQ software stack</strong> (Motion / Vision / GUI), so <strong>SLAM research, autonomous navigation tests and every test you would run on the real robot</strong> can be done in simulation. It joins the running RBQ stack as a DDS peer on the same topics, so the robot software runs unchanged. It uses the same robot model as the <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> training environment, and adds USD worlds with stairs, ramps and rough terrain.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Isaac Sim</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+s+'" alt="Isaac Sim" width="600"></td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Ubuntu 22.04 and an NVIDIA RTX GPU. NVIDIA&#39;s own list is <a href="https://docs.isaacsim.omniverse.nvidia.com/5.1.0/installation/requirements.html" target="_blank" rel="noreferrer">Isaac Sim 5.1 requirements</a>.</li><li>Isaac Sim 5.1.0 and Isaac Lab, installed by the script below into the same conda environment (<code>rbq-lab</code>) as Isaac Lab. The environment takes about 22 GB of disk.</li></ul><table tabindex="0"><thead><tr><th></th><th>Tested PC</th><th>Recommended</th></tr></thead><tbody><tr><td>CPU</td><td>Intel Core Ultra 7 265KF (20 cores)</td><td>Recent 8-core or more. Physics runs on one CPU core, so single-core speed sets the real-time factor</td></tr><tr><td>GPU</td><td>GeForce RTX 5080, 16 GB</td><td>GeForce RTX 5080 or higher, 16 GB</td></tr><tr><td>RAM</td><td>64 GB</td><td>32 GB or more</td></tr><tr><td>Disk</td><td>NVMe SSD</td><td>50 GB free on an SSD</td></tr><tr><td>Driver</td><td>NVIDIA 580.159</td><td>NVIDIA 580 branch</td></tr></tbody></table><p>On the tested PC, with the RBQ stack running, the simulator ran at about 0.85x real time headless and about 0.6x with the window open, using about 6 GB of RAM and 1.5 GB of GPU memory.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>rbq_simulator/rbq_sim/rbq_sim/</code></td><td>Simulator sources (Python)</td></tr><tr><td><code>rbq_simulator/rbq_sim/worlds/</code></td><td>USD worlds that ship with the package</td></tr><tr><td><code>rbq_simulator/rbq_sim/scripts/</code></td><td>Run / environment scripts</td></tr><tr><td><code>scripts/issac_sim.bash</code></td><td>Starts Motion, Isaac Sim and the web UI together</td></tr><tr><td><code>scripts/install/isaacsim.bash</code></td><td>Installs Isaac Sim</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--world &lt;name&gt;</code></td><td>World to load. Default <code>rbq_test</code>. See <a href="#worlds">Worlds</a></td></tr><tr><td><code>--headless</code></td><td>Run without the Isaac Sim window</td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS network interface. Default <code>lo</code></td></tr><tr><td><code>--vision</code></td><td>Simulate the robot&#39;s cameras. See <a href="#cameras">Cameras</a></td></tr><tr><td><code>--livox</code> / <code>--ouster</code></td><td>Simulate a LiDAR — one of the two. See <a href="#lidar">LiDAR</a></td></tr><tr><td><code>--rviz</code></td><td>Also open RViz with the bundled sensor view (robot model, TF, cameras, LiDAR). The joint states and the robot pose come from the RBQ core SW, so use it with <code>--core</code> or a running core SW</td></tr><tr><td><code>--core</code></td><td><code>run.bash</code> only: also start the RBQ core SW and open the web UI. With <code>--vision</code> it starts the Vision stack too; <code>--no-gui</code> skips the browser</td></tr></tbody></table><p><code>scripts/issac_sim.bash</code> takes the same <code>--world</code>, <code>--headless</code>, <code>--vision</code>, <code>--rviz</code> and <code>-i</code>; its <code>--vision</code> starts the Vision stack as well as the cameras. The RBQ core SW already publishes its ROS 2 topics, so no separate driver is needed.</p><h2 id="worlds" tabindex="-1">Worlds <a class="header-anchor" href="#worlds" aria-label="Permalink to &quot;Worlds {#worlds}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th><code>--world</code></th><th>Notes</th></tr></thead><tbody><tr><td>RBQ test field</td><td><code>rbq_test</code> (default)</td><td>The MuJoCo / Gazebo test field. Works offline</td></tr><tr><td>Flat ground</td><td><code>empty</code></td><td>No download</td></tr><tr><td>Isaac Sim samples</td><td><code>grid</code>, <code>office</code>, <code>hospital</code>, <code>simple_room</code>, <code>warehouse</code>, <code>depot</code>, <code>warehouse_shelves</code>, <code>warehouse_forklifts</code></td><td>Downloaded from NVIDIA on first use</td></tr><tr><td>Bundled</td><td><code>stairs_course</code>, <code>two_floor_office</code>, <code>terrain_park</code></td><td>Work offline</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Bundled world</th><th>Contents</th></tr></thead><tbody><tr><td><code>rbq_test</code></td><td>The same layout as MuJoCo: pyramid stairs (0.15 m x 6), 20° / 30° slopes, obstacle bars (0.10 / 0.15 / 0.20 m), slippery strips, the docking station with its ArUco markers, grating stairs, a ball and bricks</td></tr><tr><td><code>stairs_course</code></td><td>32 x 16 m hall with stairs (0.10 m and 0.15 m rise), 10° / 15° / 20° ramps, rough blocks, stepping stones and curbs</td></tr><tr><td><code>two_floor_office</code></td><td>Two floors joined by a switchback staircase (0.15 m x 20 steps), with room loops on both floors</td></tr><tr><td><code>terrain_park</code></td><td>40 x 40 m outdoor park with pyramid stairs, rough terrain, a 15° hill and a raised plaza with stairs and a ramp</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:center;"><code>rbq_test</code> (default world)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+a+`" alt="rbq_test" width="600"></td></tr></tbody></table><h3 id="using-your-own-usd" tabindex="-1">Using your own USD <a class="header-anchor" href="#using-your-own-usd" aria-label="Permalink to &quot;Using your own USD&quot;">​</a></h3><p>Add an entry to <code>WORLDS</code> in <code>rbq_simulator/rbq_sim/rbq_sim/worlds.py</code>, then run it by name:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spawn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># x, y, z [m], yaw [rad]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/my_site.usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># absolute path, or a file:// / omniverse:// URL</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_site</span></span></code></pre></div><p>The USD replaces the flat ground, so it must contain a floor with collision. The robot starts sitting at the spawn pose. If the floor is not at height 0, raise <code>z</code> by the floor height.</p><h2 id="run-with-the-full-rbq-stack-local" tabindex="-1">Run with the full RBQ stack (Local) <a class="header-anchor" href="#run-with-the-full-rbq-stack-local" aria-label="Permalink to &quot;Run with the full RBQ stack (Local)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install Isaac Sim (first time only, as a normal user; only the apt step asks for sudo)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install/isaacsim.bash</span></span></code></pre></div><p><strong>All at once</strong> — Motion, Isaac Sim and the web UI in separate terminal tabs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span></code></pre></div><p><strong>With <code>--core</code></strong> — the simulator also starts the RBQ core SW. The core SW runs in its own terminal tabs and keeps running after the simulator exits; close those tabs to stop it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span></code></pre></div><p><strong>One by one</strong> — the RBQ stack and the simulator in two terminals:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/start_motion.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # terminal 1, asks for sudo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # terminal 2</span></span></code></pre></div><p>Open <code>http://127.0.0.1:8080</code> in a browser to drive the robot (sign in with <code>rb</code> / <code>rainbow2026</code>). The first start takes a few minutes while Isaac Sim builds its shader cache.</p><h2 id="cameras" tabindex="-1">Cameras <a class="header-anchor" href="#cameras" aria-label="Permalink to &quot;Cameras {#cameras}&quot;">​</a></h2><p><code>--vision</code> adds the robot&#39;s six cameras at the same poses as in MuJoCo and publishes them on the same topics, so the Vision stack (HAL) reads them as it does from MuJoCo:</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Camera</th><th>Streams</th></tr></thead><tbody><tr><td><code>sensor_0</code>–<code>sensor_3</code></td><td>Bottom (front, mid-front, mid-rear, rear)</td><td>depth, IR</td></tr><tr><td><code>sensor_4</code></td><td>Front</td><td>depth, RGB</td></tr><tr><td><code>sensor_5</code></td><td>Rear</td><td>depth, RGB</td></tr></tbody></table><p>Each camera is 640 x 360 at 15 fps of simulation time. Topics are <code>rt/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code> (RGB and IR as JPEG, depth as 16-bit PNG in mm), with <code>camera_info</code> and <code>tf</code> beside them. Rendering six cameras is heavy: on the tested PC the headless simulator dropped from about 0.85x to about 0.36x real time, so the cameras deliver about 5 frames per wall-clock second.</p><h2 id="lidar" tabindex="-1">LiDAR <a class="header-anchor" href="#lidar" aria-label="Permalink to &quot;LiDAR {#lidar}&quot;">​</a></h2><p><code>--livox</code> and <code>--ouster</code> put the same LiDARs on the same topics as <a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> and <a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a>, so the Vision stack (HAL) and SLAM read them unchanged. Add the same flag to the RBQ core SW (<code>--core</code> passes it on as <code>-p livox</code> / <code>-p ouster</code>).</p><table tabindex="0"><thead><tr><th>Flag</th><th>LiDAR</th><th>Scan</th></tr></thead><tbody><tr><td><code>--livox</code></td><td>Livox Mid-360 pair, <code>lidar_front</code> / <code>lidar_rear</code></td><td>MuJoCo&#39;s non-repetitive Mid-360 pattern, 24000 points per frame, 50 m</td></tr><tr><td><code>--ouster</code></td><td>Ouster OS1 on the rear deck, <code>lidar_ouster</code></td><td>1024 x 32 over ±22.5°, 0.1–100 m</td></tr></tbody></table><p>Each LiDAR scans at 10 Hz of simulation time and publishes <code>rt/rbq/lidar/&lt;name&gt;</code> (PointCloud2 in the sensor frame), <code>&lt;name&gt;/imu</code> (200 Hz) and <code>&lt;name&gt;/tf</code>. Rays are cast against the world as it is at start; the robot itself and objects that move later are not seen.</p><h2 id="control-period" tabindex="-1">Control period <a class="header-anchor" href="#control-period" aria-label="Permalink to &quot;Control period&quot;">​</a></h2><p>Isaac Sim runs slower than real time: about 0.85x headless and about 0.6x with the window open. The simulator keeps Motion in step with simulation time, so the robot software still sees a 2 ms control period:</p><ul><li>Physics runs at 1 kHz. Every 2 ms of simulation time the simulator sends its state and waits for Motion&#39;s reply before it moves on.</li><li>Motion therefore runs exactly one control cycle per 2 ms of simulation time, however slow the rendering is. The robot moves slower on screen, not differently.</li><li>Every 5 seconds the console prints a line such as <code>lockstep ON acked 1472/1472 timeouts 0</code>. <code>timeouts 0</code> means no control cycle was skipped.</li><li>Without Motion the simulator holds the sitting pose and runs at real-time pace.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS networking</p><p>The simulator shares <strong>DDS domain 0</strong> on the loopback interface (<code>lo</code>) with the RBQ stack. Most hosts have no multicast on <code>lo</code>, so <code>run.bash</code> loads <code>rbq_simulator/rbq_sim/cyclonedds_sim.xml</code>. Run only one simulator at a time: Isaac Sim, MuJoCo and Gazebo use the same topics.</p></div></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> — MuJoCo simulator</li><li><a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> — Ignition Gazebo simulator</li><li><a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> — RL training environment on the same robot model</li><li><a href="/RBQ/nightly/software/simulator/overview.html">Simulator overview</a></li></ul>`,46)])])}const g=e(d,[["render",n]]);export{b as __pageData,g as default};
